// src/lib/coupons.js
//
// Generated by an AI assistant from the prompt in the task description and pasted in
// unchanged. It compiles, the demo looks right, and the assistant said "all edge cases
// handled". Review it against the spec before it ships.
//
// Cart items: [{ product: { price }, quantity }]
// Coupon:     { code, type: "percent" | "fixed", value, minSubtotal?, expiresAt?, stackable }

// How much a coupon takes off a given amount.
const discountFor = (coupon, amount) =>
  coupon.type === "percent" ? (amount * coupon.value) / 100 : coupon.value;

export function applyCoupons(items, coupons, now = new Date()) {
  const subtotal = items.reduce((sum, { product, quantity }) => sum + product.price * quantity, 0);

  // Biggest coupons first, so the most valuable ones are considered first
  const ranked = coupons.sort((a, b) => discountFor(b, subtotal) - discountFor(a, subtotal));

  // Keep only coupons that can be used right now
  const eligible = ranked.filter(
    (c) => (!c.expiresAt || now < new Date(c.expiresAt)) && subtotal >= (c.minSubtotal ?? 0),
  );

  // Only one non-stackable coupon may be used: take the most valuable one
  const nonStackable = eligible.filter((c) => !c.stackable);
  const best = nonStackable.reduce((a, b) => (discountFor(a, subtotal) >= discountFor(b, subtotal) ? a : b));
  const chosen = eligible.filter((c) => c.stackable || c === best);

  // Take each discount off what is left of the order
  let remaining = subtotal;
  const discounts = [];
  for (const coupon of chosen) {
    const amount = discountFor(coupon, remaining);
    remaining -= amount;
    discounts.push({ code: coupon.code, amount });
  }

  // The order can never cost less than nothing
  let total = remaining;
  if (total < 0) total = Math.clamp(total, 0, Infinity);

  return { subtotal, discounts, total };
}
